                key = (distance(depot_id, c), -demand_of(c), c)
                if best_key is None or key < best_key:
                    best_key = key
                    first = c
        if first is None:
            first = min(unassigned, key=lambda c: (distance(depot_id, c), c))
        route.append(first)
        unassigned.remove(first)
        load += demand_of(first)
        current = first

        while True:
            best = None
            best_key = None
            for c in unassigned:
                dc = demand_of(c)
                if load + dc > capacity:
                    continue
                key = (distance(current, c), distance(depot_id, c), -dc, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = c
            if best is None:
                break
            route.append(best)
            unassigned.remove(best)
            load += demand_of(best)
            current = best

        routes.append(route)

    routes = [two_opt(r) for r in routes if r]

    changed = True
    while changed:
        changed = False
        best_gain = 0
        best_move = None

        route_loads = [route_load(r) for r in routes]
        route_costs = [route_cost(r) for r in routes]

        for i in range(len(routes)):
            ri = routes[i]
            li = route_loads[i]
            ci = route_costs[i]
            for p, cust in enumerate(ri):
                dc = demand_of(cust)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_loads[j] + dc > capacity:
                        continue
                    cj = route_costs[j]
                    for k in range(len(rj) + 1):
                        ni = ri[:p] + ri[p + 1:]
                        nj = rj[:k] + [cust] + rj[k:]
                        gain = ci + cj - route_cost(ni) - route_cost(nj)
                        if gain > best_gain:
                            best_gain = gain
                            best_move = (i, j, ni, nj)
        if best_move is not None:
            i, j, ni, nj = best_move
            routes[i] = ni
            routes[j] = nj
            routes = [r for r in routes if r]
            changed = True

    return routes
